import { initTRPC, TRPCError } from '@trpc/server';
import { observable } from '@trpc/server/observable';
import { z } from 'zod';
import { redisSubscriber } from '../lib/redis';
import type { TrpcContext } from '../context';

const t = initTRPC.context<TrpcContext>().create();

export const tradingRouter = t.router({
  onOrderExecution: t.procedure
    .input(z.object({ accountId: z.string().min(5) }))
    .subscription(({ input, ctx }) => {
      if (!ctx.session?.userId) {
        throw new TRPCError({ code: 'UNAUTHORIZED' });
      }

      // Binds Redis pub/sub channel using client-provided accountId without ownership check
      return observable<OrderFillEvent>((emit) => {
        const channel = `trading:fills:${input.accountId}`;

        const messageHandler = (chan: string, message: string) => {
          if (chan === channel) {
            emit.next(JSON.parse(message));
          }
        };

        redisSubscriber.subscribe(channel);
        redisSubscriber.on('message', messageHandler);

        return () => {
          redisSubscriber.unsubscribe(channel);
          redisSubscriber.removeListener('message', messageHandler);
        };
      });
    }),
});

